class OrchestraXmlElement(ConfiguredBaseModel):
    """
    An XML element in a place where the XSDs accept any content, kept as written so that the file converts back unchanged.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/lmodel/fix-orchestra/fix_orchestra_common',
         'title': 'Open XML element'})

    xml_name: str = Field(default=..., description="""The name, with its namespace in braces when it has one.""", json_schema_extra = { "linkml_meta": {'domain_of': ['OrchestraXmlElement', 'OrchestraXmlAttribute']} })
    xml_attributes: Optional[list[OrchestraXmlAttribute]] = Field(default=None, description="""The element's attributes.""", json_schema_extra = { "linkml_meta": {'domain_of': ['OrchestraXmlElement']} })
    xml_text: Optional[str] = Field(default=None, description="""The text before the first child element.""", json_schema_extra = { "linkml_meta": {'domain_of': ['OrchestraXmlElement']} })
    xml_children: Optional[list[OrchestraXmlElement]] = Field(default=None, description="""The child elements, in order.""", json_schema_extra = { "linkml_meta": {'domain_of': ['OrchestraXmlElement']} })
    xml_tail: Optional[str] = Field(default=None, description="""The text after the element and before its next sibling.""", json_schema_extra = { "linkml_meta": {'domain_of': ['OrchestraXmlElement']} })

    @field_validator('xml_name')
    def pattern_xml_name(cls, v):
        pattern=re.compile(r"^(\{[^}]*\})?[^\s{}]+$")
        if isinstance(v, list):
            for element in v:
                if isinstance(element, str) and not pattern.search(element):
                    err_msg = f"Invalid xml_name format: {element}"
                    raise ValueError(err_msg)
        elif isinstance(v, str) and not pattern.search(v):
            err_msg = f"Invalid xml_name format: {v}"
            raise ValueError(err_msg)
        return v


