    fixi_other_attributes: Optional[list[OrchestraXmlAttribute]] = Field(default=None, description="""Attributes from other namespaces, kept as written.""", json_schema_extra = { "linkml_meta": {'annotations': {'xml_any': {'tag': 'xml_any', 'value': 'attributes'}},
         'domain_of': ['OrchestraBaseInterfaceV10',
                       'OrchestraInterfaceAppinfoV10',
                       'OrchestraProtocolV10',
                       'OrchestraTransportV10',
                       'OrchestraBaseInterfaceV11',
                       'OrchestraInterfaceAppinfoV11',
                       'OrchestraProtocolV11',
                       'OrchestraTransportV11']} })

    @field_validator('fixi_name')
    def pattern_fixi_name(cls, v):
        pattern=re.compile(r"^([^ \t\r\n]+( [^ \t\r\n]+)*)?$")
        if isinstance(v, list):
            for element in v:
                if isinstance(element, str) and not pattern.search(element):
                    err_msg = f"Invalid fixi_name format: {element}"
                    raise ValueError(err_msg)
        elif isinstance(v, str) and not pattern.search(v):
            err_msg = f"Invalid fixi_name format: {v}"
            raise ValueError(err_msg)
        return v


